mapper.select:
select j.id, j.article_id, j.target_code, j.status, j.scheduled_at, j.started_at, j.finished_at, j.operator_id, j.operator_name, j.error_message, a.title as article_title, a.slug as article_slug, a.status as article_status, a.del_flag as article_del_flag, r.id as result_id, r.site_url, r.external_url, j.create_by, j.create_time, j.update_by, j.update_time, j.remark, j.del_flag from content_publish_job j left join content_article a on a.id = j.article_id left join content_publish_result r on r.id = ( select max(r2.id) from content_publish_result r2 where r2.job_id = j.id and r2.del_flag = '0' ) where j.del_flag = '0'
and j.article_id = #{articleId}
and a.title like concat('%', #{articleTitle}, '%')
and j.target_code = #{targetCode}
and j.status = #{status}
and j.operator_name like concat('%', #{operatorName}, '%')
and j.create_time >= #{beginTime}
and j.create_time <= #{endTime}
order by j.create_time desc, j.id desc
